CREATE TABLE assets (id TEXT PRIMARY KEY, name TEXT NOT NULL, asset_type TEXT NOT NULL, location TEXT, status TEXT NOT NULL, metadata JSONB, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE maintenance_strategies (id TEXT PRIMARY KEY, name TEXT NOT NULL, trigger_type TEXT NOT NULL, interval_hours INTEGER, threshold NUMERIC, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE inspection_templates (id TEXT PRIMARY KEY, name TEXT NOT NULL, version INTEGER NOT NULL, items JSONB NOT NULL, active BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(name, version));
CREATE TABLE maintenance_plans (id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES assets(id), template_id TEXT NOT NULL REFERENCES inspection_templates(id), strategy_id TEXT REFERENCES maintenance_strategies(id), status TEXT NOT NULL, next_run_at TIMESTAMPTZ NOT NULL, last_run_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE maintenance_tasks (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES maintenance_plans(id), asset_id TEXT NOT NULL REFERENCES assets(id), status TEXT NOT NULL, scheduled_at TIMESTAMPTZ NOT NULL, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, assignee TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE inspection_findings (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES maintenance_tasks(id), asset_id TEXT NOT NULL REFERENCES assets(id), severity TEXT NOT NULL, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL, reported_at TIMESTAMPTZ NOT NULL, resolved_at TIMESTAMPTZ);
CREATE TABLE maintenance_history (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, action TEXT NOT NULL, actor TEXT, details JSONB, occurred_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_assets_status ON assets(status); CREATE INDEX idx_plans_due ON maintenance_plans(status,next_run_at); CREATE INDEX idx_tasks_asset ON maintenance_tasks(asset_id,status); CREATE INDEX idx_findings_asset ON inspection_findings(asset_id,status);
